typedef float vm_num_t;

class vm_thread;

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };
  protected:
    char* name;
  public:
    function(script_library_class* slc, const char* n);
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

class num_list
{
  vm_num_t* start;
  vm_num_t* finish;
  vm_num_t* end_of_storage;
public:
  unsigned size() const { return finish - start; }
  vm_num_t& operator[](unsigned index) { return start[index]; }
};

typedef num_list* vm_num_list_t;

void error(const char*, ...);

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()

#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result))) \
    error("script stack overflow")

#define SLF_DONE \
  return true

class slf_num_list_get_index_t : public script_library_class::function
  {
  public:
    // constructor required
    slf_num_list_get_index_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
    // library function parameters
    struct parms_t
      {
      // parameters
		  vm_num_list_t me;
		  vm_num_t index;
      };
    // library function execution
    virtual bool operator()(vm_stack& stack,entry_t entry)
      {
      SLF_PARMS;
	    #ifndef BUILD_BOOTABLE
		  if((parms->index >= parms->me->size()) || (parms->index < 0))
			  error("Index out of range %d", (int)parms->index);
	    #endif
	    vm_num_t result = (*parms->me)[(int)parms->index];
      SLF_RETURN;
      SLF_DONE;
      }
  };
